        "text": "ГОСТ 30971-2012 допускает работы с пенополиуретановыми утеплителями при температуре не ниже −10 °C. Но эта цифра — не универсальное разрешение на монтаж в любой мороз. У каждого герметика, ленты, праймера и монтажной пены есть собственный диапазон применения, требования к хранению и подготовке поверхности, и ориентироваться нужно по самому строгому из них."
