    "metaDescription": "Нужно ли накрывать наружный блок кондиционера на зиму: чем опасен герметичный чехол, когда нужен навес и как защитить блок от снега и наледи.",
    "summary": "Наружный блок рассчитан на улицу: герметичный чехол мешает обдуву и задерживает влагу, а работающему на обогрев блоку прямо вредит. От снега, льда и ветра защищают навес, основание или перенос по инструкции модели.",
