        "text": "Осенью наружные блоки часто заматывают полиэтиленом «от снега и мороза». Логика кажется очевидной: на улице холодно, значит технику нужно укутать. Но наружный блок изначально проектируется для размещения снаружи: производители рассчитывают его на дождь, снег, ветер и перепады температур. Его нормальная работа и естественное высыхание зависят от свободного движения воздуха. Поэтому правильный вопрос не «нужен ли чехол», а «будет ли блок работать зимой и от чего именно его защищать»."
