        "text": "Если над блоком есть карниз, кровля или балкон, с которых может сходить лёд, нужен рассчитанный защитный козырёк либо перенос блока в безопасное место. Самодельный тонкий козырёк, закреплённый вплотную к корпусу, может не выдержать удар и сам повредить оборудование."
