        "type": "p",
        "text": "Попросите зафиксировать в смете и договоре точное название профильной системы, состав стеклопакета, схему армирования, фурнитуру и полный перечень работ. Если продавец называет только бренд, этого недостаточно для осознанного выбора: у одного бренда несколько систем, и они не равнозначны."
