        "text": "Профиль и комплектующие привозят в Иркутск из других регионов, а окна собирают на местных производствах: логистика, складская программа и загрузка цеха влияют на сроки и цену не меньше, чем имя бренда. Климат добавляет свои требования: при зимних −25…−35 °C и ветре с Байкала разница между бюджетной и тёплой серией проявляется на откосах и в счетах за отопление. В панельных домах Иркутска проёмы часто имеют отклонения от проекта в 1–2 см, а в старом фонде в центре встречаются рассохшиеся деревянные проёмы, которым нужен аккуратный монтажный узел. И в том и в другом случае качество окна определяют замер, стеклопакет под задачу и шов по ГОСТ 30971-2012, а не шильдик на раме. Для первых этажей у дороги добавляется шумовой фактор: там выбор стеклопакета важнее серии профиля. Если вы выбираете окна для квартиры в Иркутске, закажите замер и попросите обе сметы на один и тот же проём: тогда сравнивать будет что. Отдельная местная особенность — сроки: редкие серии и цветные профили под заказ везут дольше типовых, поэтому планы на замену лучше строить заранее."
