        "text": "Готового рейтинга «лучших моделей» не существует: у каждой линейки мощность, шум и рабочий диапазон различаются по типоразмерам, а честный топ требовал бы одинаковых испытаний. Сравнивайте конкретный полный индекс по паспорту: холодопроизводительность и её минимум, SEER и SCOP, шум, диапазон температур, сервис и смету монтажа."
