          "Холодопроизводительность: номинал и минимум. Подбирают её по теплопритокам комнаты, а площадь — только предварительный ориентир.",
          "Сезонная эффективность: SEER для охлаждения и SCOP для обогрева, посчитанные по одной методике, а не отдельная рекламная цифра.",
          "Шум на одной и той же скорости в дБ(А): уровень зависит от режима и расстояния до прибора.",
