          "SHUFT Berg SFTO: проверьте, какой именно блок и комплектация указаны в предложении, а также условия сервиса и наличие запасных частей в регионе.",
          "Axioma Серия H R32: внутри серии бывают разные исполнения, поэтому сверяйте полный код, тип управления и хладагент по документации конкретного изделия, а не по общему названию.",
          "Ballu Tessey DC BSTI: запросите паспорт конкретного типоразмера и проверьте показатели охлаждения, потребления, шума и гарантию.",
