        "text": "В Иркутске у выбора есть местная специфика. Лето короткое, но панельные дома с южными и западными окнами прогреваются до +28…+30 °C, и кондиционер работает интенсивно два-три месяца. Зима длинная: если вы рассчитываете на обогрев, проверяйте паспортный диапазон — большинство бытовых моделей греют до −5…−7 °C, версии с зимним комплектом — до −15…−25 °C, а при −35 °C бытовая сплит-система штатно не работает. Для спальни отдельно сравните шум на низкой скорости и направление потока, а перед сезоном покажите блок сервису: после зимы в наружном блоке скапливаются пыль и листья. Вторая местная тема — сервис: в Иркутске важны не только гарантия, но и наличие запчастей, авторизованного сервиса и монтажников, знакомых с конкретной маркой. Третья — монтаж: в панельных сериях Иркутска проёмы часто отличаются от проектных, поэтому длину трассы, бурение и отвод конденсата считают заранее, до покупки. Для пригорода — Хомутово, Шелехов, Ангарск — и частного сектора добавьте проверку электропитания и высоты установки наружного блока. Каталог моделей и подбор — в разделе [кондиционеры](/kondicionery)."
