        "text": "Энергосберегающее покрытие уменьшает потери тепла через стекло, заполнение камер инертным газом снижает конвекцию внутри пакета. Для уличного шума важны разные толщины стёкол в пакете. По ГОСТ 24866 паспортная точка росы герметичного стеклопакета — не выше −45 °C, а конденсат между стёклами означает, что герметичность нарушена и пакет пора менять. Просите характеристики всего оконного блока, а не только профиля."
