    "title": "Бризер или рекуператор: что выбрать для квартиры в Иркутске — техническое сравнение с расчётами окупаемости",
    "category": "Вентиляция",
    "summary": "Бризер подаёт воздух в комнату, рекуператор добавляет вытяжку с возвратом тепла. Выбор определяют расход воздуха, шум, фильтры, монтаж и отопление, а окупаемость считают по расчёту, а не по паспортному проценту.",
