        "text": "Универсального ответа нет: бризер и рекуператор решают разные задачи. Бризер подаёт наружный воздух в комнату, а вытяжка остаётся штатной. Рекуператор организует приток и удаление воздуха, возвращая часть тепла вытяжки притоку. Для квартиры в Иркутске выбор сводится к схеме: нужен только приток или баланс с вытяжкой."
