    "summary": "Кондиционер с функцией теплового насоса может обогревать помещение, но допустимая наружная температура, мощность и эффективность зависят от конкретной модели и условий. Проверяйте паспортные характеристики при нужной температуре; «инвертор» и «зимний комплект» сами по себе не гарантируют работу в сильный мороз.",
