    "summary": "Духота может быть связана с недостаточным воздухообменом, но CO₂ — лишь один из индикаторов, а не универсальная причина симптомов и не медицинский порог. Измеритель показывает динамику вентиляции при конкретной загрузке помещения; для решения проблемы нужно проверить приток, вытяжку и переток воздуха.",
