        "text": "Ощущение духоты может появляться по разным причинам: недостаточный воздухообмен, повышенная влажность, жара, запахи, загрязнители или особенности самочувствия. Углекислый газ (CO₂) часто используют как один из индикаторов вентиляции в помещении, но по одному числу нельзя поставить диагноз или объяснить головную боль."
