        "type": "p",
        "text": "Пена заполняет пространство и снижает теплопередачу, но её свойства зависят от условий нанесения и защиты. Пыльное, мокрое, непрочное или обледеневшее основание может помешать сцеплению; открытый материал может повреждаться ультрафиолетом и влагой. Видимая пена под откосом не показывает, как выполнены крепёж и скрытые слои."
